'use strict';
/* Viewfinder Flip Carousel, adapted from the supplied 3dflip.txt.
   Fixed-size slots translate instead of animating layout widths. No frame loop. */
(()=>{
 const clamp=(i,n)=>Math.max(0,Math.min(n-1,Math.round(i)));
 function springEasing(bounce=.18,duration=.44,samples=48){const zeta=1-Math.min(Math.max(bounce,0),.9),w=2*Math.PI/Math.max(duration,.05),wd=w*Math.sqrt(1-zeta*zeta),T=Math.log(1000)/(zeta*w);const points=Array.from({length:samples+1},(_,i)=>i===samples?1:Number((1-Math.exp(-zeta*w*i/samples*T)*(Math.cos(wd*i/samples*T)+(zeta*w/wd)*Math.sin(wd*i/samples*T))).toFixed(4)));return {easing:'linear('+points.join(',')+')',ms:Math.round(T*1000)};}
 const arrow=dir=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${dir<0?'m15 5-7 7 7 7':'m9 5 7 7-7 7'}"/></svg>`;
 function markup(){return `<section class="flip-carousel" tabindex="0" role="region" aria-roledescription="carousel" aria-label="Chọn môn học bằng thẻ lật"><div class="flip-eyebrow"><span>CHỌN MỘT MÔN BẠN MUỐN HỌC</span><span>03 MÔN HỌC</span></div><div class="flip-stage">${SUBJECTS.map((s,i)=>`<div class="flip-slot" role="group" aria-roledescription="thẻ môn học" aria-label="${i+1} trên ${SUBJECTS.length}"><div class="flip-holder"><button class="flip-photo" type="button" data-flip-card="${i}" aria-label="${i===0?'Mở':'Xem'} môn ${s.title}" ${i===0?'aria-current="true"':''} tabindex="${i===0?0:-1}">${window.KienV9.courseCover(s)}</button></div></div>`).join('')}<div class="flip-frame" aria-hidden="true"></div></div><div class="flip-readout"><div><span class="flip-current-code">HIS / 01</span><h3 class="flip-current-title">${SUBJECTS[0].title}</h3><p class="flip-current-count">${SUBJECTS[0].count}</p></div><button class="btn flip-open" type="button" data-flip-open>Vào môn học ${arrow(1)}</button></div><div class="flip-controls"><button class="flip-control" type="button" data-flip-prev aria-label="Môn trước" disabled>${arrow(-1)}</button><div class="flip-dots" role="group" aria-label="Chọn thẻ môn học">${SUBJECTS.map((s,i)=>`<button type="button" class="flip-dot" data-flip-to="${i}" aria-label="Xem môn ${s.title}" ${i===0?'aria-current="true"':''}><span></span></button>`).join('')}</div><span class="flip-counter" aria-hidden="true">01 / 03</span><button class="flip-control" type="button" data-flip-next aria-label="Môn tiếp theo">${arrow(1)}</button></div><p class="flip-hint">Chạm thẻ hoặc dùng nút để chọn môn.</p><p class="sr-only flip-announcement" role="status" aria-live="polite" aria-atomic="true"></p></section>`;}
 let dispose=()=>{};
 function mount(){dispose();dispose=()=>{};const root=document.querySelector('.flip-carousel');if(!root)return;const slots=[...root.querySelectorAll('.flip-slot')],photos=[...root.querySelectorAll('.flip-photo')],holders=[...root.querySelectorAll('.flip-holder')];let active=0,metrics=null,pointer=null,suppressUntil=0,timer=0;
  const motion=()=>window.KienUI.motionEnabled();const spring=springEasing();root.style.setProperty('--flip-spring',CSS.supports('transition-timing-function',spring.easing)?spring.easing:'cubic-bezier(.22,1,.36,1)');root.style.setProperty('--flip-settle',spring.ms+'ms');
  function render(announce=false){if(!metrics)return;const s=SUBJECTS[active],{folded,open}=metrics;root.dataset.active=String(active);root.classList.toggle('flip-static',!motion());
   slots.forEach((slot,i)=>{const side=i<active?1:i>active?-1:0,delta=i-active,x=side===0?0:delta*folded+(i<active?-1:1)*(open-folded)/2;slot.style.transform=`translate3d(${x}px,0,0)`;slot.style.zIndex=String(SUBJECTS.length-Math.abs(delta));holders[i].style.transform=`rotateY(${side*60}deg) rotateZ(${side*90}deg)`;photos[i].tabIndex=i===active?0:-1;photos[i].setAttribute('aria-label',(i===active?'Mở':'Xem')+' môn '+SUBJECTS[i].title);if(i===active)photos[i].setAttribute('aria-current','true');else photos[i].removeAttribute('aria-current');});
   root.querySelectorAll('[data-flip-to]').forEach((b,i)=>{if(i===active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');});root.querySelector('[data-flip-prev]').disabled=active===0;root.querySelector('[data-flip-next]').disabled=active===SUBJECTS.length-1;root.querySelector('.flip-current-code').textContent=s.code+' / 0'+(active+1);root.querySelector('.flip-current-title').textContent=s.title;root.querySelector('.flip-current-count').textContent=s.count;root.querySelector('.flip-counter').textContent='0'+(active+1)+' / 0'+SUBJECTS.length;root.querySelector('[data-flip-open]').setAttribute('aria-label','Vào môn '+s.title);if(announce)root.querySelector('.flip-announcement').textContent=`Môn ${active+1} trên ${SUBJECTS.length}: ${s.title}, ${s.count}`;
  }
  function measure(){const w=root.clientWidth;if(!w)return;const size=Math.round(Math.min(264,Math.max(160,w*.61))),folded=Math.round(Math.min(54,Math.max(28,w*.10)));const sig=size+':'+folded;if(metrics?.sig===sig)return;root.classList.add('flip-measuring');metrics={size,folded,open:size+56,sig};root.style.setProperty('--flip-size',size+'px');render();root.getBoundingClientRect();root.classList.remove('flip-measuring');}
  function go(index,focus=false){const next=clamp(index,SUBJECTS.length);if(next===active)return;active=next;clearTimeout(timer);if(motion()){root.classList.add('flip-moving');timer=setTimeout(()=>root.classList.remove('flip-moving'),spring.ms+60);}render(true);if(focus)photos[active].focus({preventScroll:true});}
  function open(){openSubject(SUBJECTS[active].id);window.scrollTo(0,0);}
  const click=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-flip-card')){if(performance.now()<suppressUntil)return;const i=Number(b.dataset.flipCard);if(i===active)open();else go(i);}else if(b.hasAttribute('data-flip-prev'))go(active-1);else if(b.hasAttribute('data-flip-next'))go(active+1);else if(b.hasAttribute('data-flip-to'))go(Number(b.dataset.flipTo));else if(b.hasAttribute('data-flip-open'))open();};
  const key=e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;let next;if(e.key==='ArrowRight')next=active+1;else if(e.key==='ArrowLeft')next=active-1;else if(e.key==='Home')next=0;else if(e.key==='End')next=SUBJECTS.length-1;else if((e.key==='Enter'||e.key===' ')&&e.target===root){e.preventDefault();open();return;}else return;e.preventDefault();go(next,e.target.matches('.flip-photo'));};
  const down=e=>{if(e.isPrimary===false||e.button!==0||!e.target.closest('.flip-stage'))return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,axis:null,done:false};};
  const move=e=>{if(!pointer||pointer.id!==e.pointerId||pointer.done)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(!pointer.axis){if(Math.abs(dy)>8&&Math.abs(dy)>=Math.abs(dx)){pointer.axis='vertical';pointer.done=true;return;}if(Math.abs(dx)>16&&Math.abs(dx)>Math.abs(dy)*1.5)pointer.axis='horizontal';}if(pointer.axis==='horizontal'&&Math.abs(dx)>45){pointer.done=true;suppressUntil=performance.now()+500;go(active+(dx<0?1:-1));}};
  const end=e=>{if(pointer?.id!==e.pointerId)return;if(pointer.axis||e.type==='pointercancel')suppressUntil=performance.now()+350;pointer=null;};
  const sync=()=>{if(!motion()){clearTimeout(timer);root.classList.remove('flip-moving');}render();};
  root.addEventListener('click',click);root.addEventListener('keydown',key);root.addEventListener('pointerdown',down,{passive:true});root.addEventListener('pointermove',move,{passive:true});root.addEventListener('pointerup',end,{passive:true});root.addEventListener('pointercancel',end,{passive:true});root.addEventListener('pointerleave',end,{passive:true});document.addEventListener('kien-motion-change',sync);const ro=new ResizeObserver(measure);ro.observe(root);measure();
  dispose=()=>{clearTimeout(timer);ro.disconnect();root.removeEventListener('click',click);root.removeEventListener('keydown',key);root.removeEventListener('pointerdown',down);root.removeEventListener('pointermove',move);root.removeEventListener('pointerup',end);root.removeEventListener('pointercancel',end);root.removeEventListener('pointerleave',end);document.removeEventListener('kien-motion-change',sync);};
 }
 window.KienFlip={markup,mount};
})();
